make_fdr_marker_legend <- function(significant_results) {

  required_columns <- c(
    "FDR"
  )

  missing_columns <- setdiff(
    required_columns,
    colnames(significant_results)
  )

  if (length(missing_columns) > 0L) {
    stop(
      "FDR legend input is missing required column(s): ",
      paste(missing_columns, collapse = ", "),
      call. = FALSE
    )
  }

  n_fdr_005 <- sum(
    !is.na(significant_results$FDR) &
      significant_results$FDR < 0.05
  )

  n_fdr_001 <- sum(
    !is.na(significant_results$FDR) &
      significant_results$FDR < 0.01
  )

  n_fdr_0001 <- sum(
    !is.na(significant_results$FDR) &
      significant_results$FDR < 0.001
  )

  ComplexHeatmap::Legend(
    title = "FDR marker",

    labels = c(
      paste0(
        "FDR < 0.05 (n = ",
        n_fdr_005,
        ")"
      ),
      paste0(
        "FDR < 0.01 (n = ",
        n_fdr_001,
        ")"
      ),
      paste0(
        "FDR < 0.001 (n = ",
        n_fdr_0001,
        ")"
      )
    ),

    graphics = list(
      function(x, y, w, h) {
        grid::grid.text(
          "*",
          x = x,
          y = y,
          gp = grid::gpar(
            fontsize = 10,
            fontface = "bold"
          )
        )
      },

      function(x, y, w, h) {
        grid::grid.text(
          "**",
          x = x,
          y = y,
          gp = grid::gpar(
            fontsize = 10,
            fontface = "bold"
          )
        )
      },

      function(x, y, w, h) {
        grid::grid.text(
          "***",
          x = x,
          y = y,
          gp = grid::gpar(
            fontsize = 10,
            fontface = "bold"
          )
        )
      }
    ),

    grid_width = grid::unit(
      7,
      "mm"
    ),

    grid_height = grid::unit(
      4,
      "mm"
    ),

    title_gp = grid::gpar(
      fontsize = 9,
      fontface = "bold"
    ),

    labels_gp = grid::gpar(
      fontsize = 8
    )
  )
}


