  tibble::as_tibble()

required_interaction_columns <- c(
  "cluster_id",
  "ensembl_gene_id",
  "gene",
  "logFC",
  "PValue",
  "FDR",
  "mean_percent_positive_spots_Male_Neurotypical",
  "mean_percent_positive_spots_Male_ASD",
  "mean_percent_positive_spots_Female_Neurotypical",
  "mean_percent_positive_spots_Female_ASD"
)

