  stop(
    "Interaction results are missing required columns: ",
    paste(missing_interaction_columns, collapse = ", "),
call. = FALSE
  )
}

significant_interaction <- interaction_results |>
  dplyr::filter(
    !is.na(.data$FDR),
    .data$FDR < fdr_threshold
  ) |>
  dplyr::mutate(
cluster_id = as.character(.data$cluster_id),
interaction_direction = dplyr::case_when(
      .data$logFC > 0 ~ "Positive logFC",
      .data$logFC < 0 ~ "Negative logFC",
      TRUE ~ "Zero logFC"
    ),
max_mean_percent = pmax(
      .data$mean_percent_positive_spots_Male_Neurotypical,
      .data$mean_percent_positive_spots_Male_ASD,
      .data$mean_percent_positive_spots_Female_Neurotypical,
      .data$mean_percent_positive_spots_Female_ASD,
na.rm = TRUE
    )
  ) |>
  dplyr::arrange(
    as.integer(.data$cluster_id),
    factor(
      .data$interaction_direction,
levels = c(
        "Positive logFC",
        "Negative logFC",
        "Zero logFC"
      )
    ),
    .data$FDR,
    dplyr::desc(abs(.data$logFC))
  )

if (nrow(significant_interaction) == 0L) {
  stop(
    "No interaction result satisfies FDR < ",
    fdr_threshold,
call. = FALSE
  )
}

significant_clusters <- sort(
  unique(as.integer(significant_interaction$cluster_id))
)

significant_cluster_ids <- as.character(significant_clusters)

missing_model_clusters <- setdiff(
  significant_cluster_ids,
  names(edgeR_perCluster_modelObjects)
)

if (length(missing_model_clusters) > 0L) {
  stop(
    "Model RData is missing significant cluster(s): ",
    paste(missing_model_clusters, collapse = ", "),
call. = FALSE
  )
}

message(
  "Significant cluster-gene results: ",
  nrow(significant_interaction)
)

message(
  "Unique genes: ",
  length(unique(significant_interaction$gene))
)

message(
  "Significant clusters: ",
  paste(significant_cluster_ids, collapse = ", ")
)


# ==============================================================================
# 9. Extract sample metadata directly from DGEList objects
# ==============================================================================

sample_metadata_list <- lapply(
  significant_cluster_ids,
  function(cluster_id_current) {

    model_object <-
      edgeR_perCluster_modelObjects[[cluster_id_current]]

    if (is.null(model_object$dge)) {
      stop(
        "DGEList is missing for cluster ",
        cluster_id_current,
call. = FALSE
      )
    }

    dge_samples <- model_object$dge$samples |>
      tibble::rownames_to_column("dge_rowname") |>
      tibble::as_tibble()

    required_dge_sample_columns <- c(
      "sample_ID",
      "fmt_donor_group",
      "sex"
    )

    missing_dge_sample_columns <- setdiff(
      required_dge_sample_columns,
      colnames(dge_samples)
    )

    if (length(missing_dge_sample_columns) > 0L) {
      stop(
        "DGEList sample metadata for cluster ",
        cluster_id_current,
        " is missing: ",
        paste(missing_dge_sample_columns, collapse = ", "),
call. = FALSE
      )
    }

    dge_samples |>
      dplyr::transmute(
sample_ID = as.character(.data$sample_ID),
fmt_donor_group = as.character(.data$fmt_donor_group),
sex = as.character(.data$sex)
      )
  }
)

sample_metadata <- sample_metadata_list |>
  dplyr::bind_rows() |>
  dplyr::distinct(
    .data$sample_ID,
    .data$fmt_donor_group,
    .data$sex
  )

metadata_conflicts <- sample_metadata |>
  dplyr::count(.data$sample_ID, name = "n_metadata_rows") |>
  dplyr::filter(.data$n_metadata_rows > 1L)

if (nrow(metadata_conflicts) > 0L) {
  stop(
    "Conflicting Sex/Group metadata found for sample(s): ",
    paste(metadata_conflicts$sample_ID, collapse = ", "),
call. = FALSE
  )
}

sample_metadata <- sample_metadata |>
  dplyr::mutate(
