      .data$sex,
      .data$fmt_donor_group,
      .data$combined_group
    ),
n = Inf
)


# ==============================================================================
# 10. Calculate sample-level TMM-CPM directly from every cluster DGEList
# ==============================================================================

cluster_cpm_matrices <- lapply(
  significant_cluster_ids,
  function(cluster_id_current) {

    dge <-
      edgeR_perCluster_modelObjects[[cluster_id_current]]$dge

    cpm_matrix <- edgeR::cpm(
      dge,
normalized.lib.sizes = TRUE,
log = FALSE
    )

    if (is.null(rownames(cpm_matrix))) {
      stop(
        "TMM-CPM matrix has no gene IDs for cluster ",
        cluster_id_current,
call. = FALSE
      )
    }

    if (is.null(colnames(cpm_matrix))) {
      stop(
        "TMM-CPM matrix has no sample IDs for cluster ",
        cluster_id_current,
call. = FALSE
      )
    }

    cpm_matrix
  }
)

names(cluster_cpm_matrices) <- significant_cluster_ids


# ==============================================================================
# 11. Build one cluster-gene x sample CPM matrix
# ==============================================================================

sample_level_cpm_matrix <- matrix(
  NA_real_,
nrow = nrow(significant_interaction),
ncol = length(sample_order),
dimnames = list(
    NULL,
    sample_order
  )
)

row_ids <- paste0(
  ifelse(
    is.na(significant_interaction$gene) |
      significant_interaction$gene == "",
    significant_interaction$ensembl_gene_id,
    significant_interaction$gene
  ),
  " [C",
  significant_interaction$cluster_id,
  "]"
)

# The cluster tag makes repeated gene symbols unambiguous without changing
# the official gene symbol itself, e.g. Ttr [C14] versus Ttr [C15].
if (anyDuplicated(row_ids) > 0L) {
  duplicated_labels <- unique(row_ids[duplicated(row_ids)])
  stop(
    "Duplicated gene-cluster row labels detected: ",
    paste(duplicated_labels, collapse = ", "),
call. = FALSE
  )
}
rownames(sample_level_cpm_matrix) <- row_ids

for (row_index in seq_len(nrow(significant_interaction))) {

  current_cluster <-
    significant_interaction$cluster_id[[row_index]]

  current_gene_id <-
    significant_interaction$ensembl_gene_id[[row_index]]

  current_cpm_matrix <-
    cluster_cpm_matrices[[current_cluster]]

  gene_match <- match(
    current_gene_id,
    rownames(current_cpm_matrix)
  )

  if (is.na(gene_match)) {
    stop(
      "Gene ",
      current_gene_id,
      " is missing from the tested DGEList genes for cluster ",
      current_cluster,
call. = FALSE
    )
  }

  available_samples <- intersect(
    sample_order,
    colnames(current_cpm_matrix)
  )

  sample_level_cpm_matrix[
    row_index,
    available_samples
  ] <- current_cpm_matrix[
    gene_match,
    available_samples,
drop = TRUE
  ]
}

if (all(is.na(sample_level_cpm_matrix))) {
  stop(
    "The complete cluster-gene CPM matrix contains only NA values.",
call. = FALSE
  )
}

number_missing_before_imputation <- sum(is.na(sample_level_cpm_matrix))
number_imputed_values <- 0L
number_rows_with_imputation <- 0L

if (isTRUE(impute_missing_by_group_mean)) {

  imputation_output <- impute_cpm_by_group_mean(
cpm_matrix = sample_level_cpm_matrix,
sample_metadata = sample_metadata,
fallback_to_row_mean = imputation_fallback_to_row_mean
  )

  sample_level_cpm_matrix <- imputation_output$matrix
  imputation_mask <- imputation_output$mask
  number_imputed_values <- imputation_output$number_imputed
  number_rows_with_imputation <-
    imputation_output$number_rows_with_imputation

  message(
    "Missing sample-cluster CPM values before imputation: ",
    number_missing_before_imputation
  )
  message(
    "CPM values imputed by within-group mean: ",
    number_imputed_values
  )
  message(
    "Heatmap rows containing at least one imputed value: ",
    number_rows_with_imputation
  )

} else {

  imputation_mask <- matrix(
    FALSE,
nrow = nrow(sample_level_cpm_matrix),
ncol = ncol(sample_level_cpm_matrix),
dimnames = dimnames(sample_level_cpm_matrix)
  )
}


