max_mean_percent_annotation <- ComplexHeatmap::AnnotationFunction(
which = "row",

width = grid::unit(
    5.5,
    "mm"
  ),

var_import = list(
values = row_annotation_table$max_mean_percent,
labels = percent_annotation_labels,
text_colours = percent_annotation_text_colour,
colour_function = max_mean_percent_color_function,
font_size = annotation_row_font_size
  ),

fun = function(index) {

    n_current <- length(
      index
    )

    y_positions <- 1 - (
      seq_len(
        n_current
      ) - 0.5
    ) / n_current

    current_values <- values[
      index
    ]

    current_labels <- labels[
      index
    ]

    current_text_colours <- text_colours[
      index
    ]

    current_fill <- rep(
      "grey90",
      n_current
    )

    finite_values <- is.finite(
      current_values
    )

    current_fill[
      finite_values
    ] <- colour_function(
      current_values[
        finite_values
      ]
    )

    grid::grid.rect(
x = grid::unit(
        0.5,
        "npc"
      ),

y = grid::unit(
        y_positions,
        "npc"
      ),

width = grid::unit(
        1,
        "npc"
      ),

height = grid::unit(
        1 / n_current,
        "npc"
      ),

gp = grid::gpar(
fill = current_fill,
col = NA
      )
    )

    grid::grid.text(
label = current_labels,

x = grid::unit(
        0.5,
        "npc"
      ),

y = grid::unit(
        y_positions,
        "npc"
      ),

gp = grid::gpar(
col = current_text_colours,
fontsize = font_size,
fontface = "bold"
      )
    )
  }
)


